dict(toc='Right to die: suicide, euthanasia, living will', id=66, title='RIGHT TO DIE · SUICIDE · EUTHANASIA · LIVING WILL', part=0, icon='scale', prio='L',
 pyq=NOPYQ + 'pp. 12-14',
 simple='Art 21 gives a right to die with dignity in recognised end-of-life situations, not a right to end life at will (Gian Kaur). Attempted suicide is now treated as a mental-health matter. Passive euthanasia and living wills were recognised in Aruna Shanbaug and Common Cause; Harish Rana (2026) covers withdrawing nutrition.',
 nodes=[
 sec('SUICIDE AND DECRIMINALISATION', 'b'),
 t('<b>Why life is different</b>', 'we can speak or not speak, move or not move; but <b>death is irreversible</b>, so the logic does not carry over directly'),
 t('<b>Legal position</b>',
   '<b>IPC s.309</b> punished an unsuccessful attempt',
   '<b>Mental Healthcare Act, 2017, s.115:</b> <b>presumption of severe stress</b>; care, treatment, rehabilitation',
   '<b>BNS s.226:</b> only an attempt <b>to compel or restrain a public servant</b>; the general s.309 offence is <b>not retained</b>'),
 two([t('<b>For decriminalisation</b>', '<b>compassion</b>', 'odd to punish an attempt but not the act', 'encourages treatment', 'failure of social support', '<b>golden hour:</b> fear of case delays aid', 'global trend to care')],
     [t('<b>Against</b>', '<b>social consequences</b> for family and society', '<b>State duty</b> to protect life')]),
 bx('ye', '<b>Gian Kaur v. State of Punjab (1996):</b> upheld then-s.309; <b>right to life does not include a right to die</b>; distinguished ending life from <b>dignity in the natural process of dying</b>. <b>Law Commission:</b> 42nd Report (1971) and 210th Report (2008) recommended repeal.'),
 sec('EUTHANASIA', 'r'),
 tb(['Type', 'Meaning'],
    ['<b>Active</b>', 'direct act, e.g. lethal drug, causes death'],
    ['<b>Passive</b>', 'withholding or withdrawing life-sustaining treatment in legally recognised cases'],
    ['<b>Voluntary</b>', 'patient\'s informed wish'], ['<b>Non-voluntary</b>', 'patient cannot decide; legal decision process needed'], ['<b>Involuntary</b>', 'against the patient\'s wishes']),
 two([t('<b>For</b>', 'ends suffering', 'informal withdrawals already happen', 'financial burden', 'scarce ICU resources')],
     [t('<b>Against</b>', 'medical ethics (duty to preserve life)', 'abuse by vested interests', 'unexpected recovery', 'less research incentive', 'family convenience over patient interest')]),
 tl(('2011', '<b>Aruna Shanbaug:</b> passive euthanasia allowed under strict conditions; High Court oversight and medical opinion'),
    ('2016', 'Medical Treatment of Terminally Ill Patients Bill: <b>not enacted</b>'),
    ('2018', '<b>Common Cause:</b> <b>right to die with dignity</b> part of Art 21; passive euthanasia and <b>Advance Medical Directives (living wills)</b> recognised; no general right to end life'),
    ('2023', '<b>Modified Common Cause guidelines:</b> simpler procedure, revised medical boards, <b>no routine High Court approval</b>'),
    ('2026', '<b>Harish Rana:</b> <b>Clinically Assisted Nutrition and Hydration (CANH)</b> can be medical treatment capable of withdrawal; stress on best interests, medical opinion, family consultation, safeguards <i>(verify)</i>')),
 bx('gr', '<b>Living will:</b> a competent adult records wishes on future life-sustaining treatment if they lose capacity. <b>Key distinction:</b> Art 21 protects dying with dignity in recognised end-of-life situations, <b>not</b> an unrestricted right to end life.'),
 ],
 recall=[('Mental Healthcare Act section', '115, presumption of severe stress'), ('BNS section on attempt', '226, only to compel a public servant'), ('Gian Kaur 1996', 'no right to die under Art 21'), ('Aruna Shanbaug', '2011, passive euthanasia'), ('Common Cause 2018', 'dignity in dying; living wills'), ('2023 change', 'no routine HC approval'), ('Harish Rana 2026', 'CANH withdrawal (verify)')]),

